const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve(__dirname, '..');
const folder = path.join(root, 'assets/fuse-art2');
const art = {};
for (const file of fs.readdirSync(folder).sort()) {
  if (!file.endsWith('.webp')) continue;
  art[path.basename(file, '.webp')] = 'data:image/webp;base64,' + fs.readFileSync(path.join(folder, file)).toString('base64');
}
fs.writeFileSync(path.join(root, 'src/fuse-art-data.js'),
  '// Generated by node dev/pack-fuse-art.cjs from assets/fuse-art2.\nconst FUSE_ART_DATA = ' +
  JSON.stringify(art, null, 2) + ';\n');
